package com.andye.warmod.rocket;import com.andye.warmod.warhead.WarheadPayloadType;import org.jspecify.annotations.Nullable;public enum RocketPayloadType {HE(3.0,14,.9,null),CONVENTIONAL_ICBM(2.3,24,1.7,WarheadPayloadType.CONVENTIONAL),NUCLEAR_ICBM(1.9,40,2.1,WarheadPayloadType.NUCLEAR);private final double speed,length;private final int cooldown;private final @Nullable WarheadPayloadType warhead;RocketPayloadType(double speed,int cooldown,double length,@Nullable WarheadPayloadType warhead){this.speed=speed;this.cooldown=cooldown;this.length=length;this.warhead=warhead;}public double speed(){return speed;}public int cooldown(){return cooldown;}public double length(){return length;}public @Nullable WarheadPayloadType warhead(){return warhead;}public static RocketPayloadType byId(int id){var v=values();return v[Math.max(0,Math.min(v.length-1,id))];}}